/* From Uiverse.io by G4b413l - Tags: card */
.__UIV_SCOPE__ .card {
  position: relative;
  width: 11.875em;
  height: 16.5em;
  box-shadow: 0px 1px 13px rgba(0,0,0,0.1);
  cursor: pointer;
  transition: all 120ms;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  padding: 0.5em;
  padding-bottom: 3.4em;
}

.__UIV_SCOPE__ .card::after {
  content: "Add to Cart";
  padding-top: 1.25em;
  padding-left: 1.25em;
  position: absolute;
  left: 0;
  bottom: -60px;
  background: #00AC7C;
  color: #fff;
  height: 2.5em;
  width: 90%;
  transition: all 80ms;
  font-weight: 600;
  text-transform: uppercase;
  opacity: 0;
}

.__UIV_SCOPE__ .card .title {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 0.9em;
  position: absolute;
  left: 0.625em;
  bottom: 1.875em;
  font-weight: 400;
  color: #000;
}

.__UIV_SCOPE__ .card .price {
  font-family: Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
  font-size: 0.9em;
  position: absolute;
  left: 0.625em;
  bottom: 0.625em;
  color: #000;
}

.__UIV_SCOPE__ .card:hover::after {
  bottom: 0;
  opacity: 1;
}

.__UIV_SCOPE__ .card:active {
  transform: scale(0.98);
}

.__UIV_SCOPE__ .card:active::after {
  content: "Added !";
  height: 3.125em;
}

.__UIV_SCOPE__ .text {
  max-width: 55px;
}

.__UIV_SCOPE__ .image {
  background: rgb(241, 241, 241);
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
}
